__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"body",{enumerable:!0,get:function(){return n}});const n={id:'body',title:'Space',subtitle:'Feel your body and the space around it',ambient:{bed:'drift',level:.7,binaural:'theta'},scripts:{short:"\nNow bring your attention to your hands.\n\nFeel them from the inside. Their weight. Their warmth.\n[pause 4s]\nNow let your attention widen to the space around your hands. The air touching your skin. The space between each finger.\n[pause 6s]\nMove your attention to your face, and then to the space surrounding your face.\n[pause 6s]\nNow your chest, and the space around your chest. In front. Behind. On each side.\n[pause 6s]\nNow sense the space around your whole body, all at once.\n[pause 5s]\nLet your awareness grow wider than your body. As wide as the room.\n[silence]\nRest here, as open space.\n",medium:"\nNow let your attention gather at the top of your head.\n\nFeel the crown of your head. And now feel the space just above it, the air resting there.\n[pause 8s]\nMove your attention to your eyes. Let them rest heavy in their sockets. And now sense the space in front of your eyes, and the space around them.\n[pause 8s]\nYour jaw and throat. Let them soften. And the space around your neck, front and back.\n[pause 8s]\nYour shoulders, and the space above and around them.\n[pause 8s]\nYour hands. Feel their weight, and then the space around your hands. Between your fingers. Around your palms.\n[pause 10s]\nYour chest. Feel it rise and fall. Now sense the space in front of your chest, and behind your back.\n[pause 10s]\nYour hips and legs. And the volume of space around them.\n[pause 8s]\nYour feet, and the space beneath and around your feet.\n[pause 10s]\nNow become aware of the space your whole body takes up. And then the space all around your body, extending in every direction.\n[pause 10s]\nLet your awareness keep expanding, past your skin, past the walls of the room.\n[silence]\nYou are not only a body here. You are the awareness that holds all this space.\n",long:"\nNow we will move slowly through the body, and the space around it.\n\nThere is no right way to feel this. Simply bring your attention to each place, and notice whatever is there. Then let your attention widen into the space around it.\n\nBegin at the top of your head. Feel the crown. Perhaps a tingle, perhaps warmth, perhaps nothing at all.\n[pause 8s]\nNow sense the space just above your head. The quiet air resting there.\n[pause 12s]\nBring your attention to your forehead. Let it go wide and smooth. And now sense the space in front of your forehead.\n[pause 12s]\nYour eyes. Let them rest heavy and still. Now notice the space around your eyes, and the dark, open space in front of them.\n[pause 12s]\nYour jaw. Let it hang loose. And the space around your jaw and cheeks.\n[pause 10s]\nYour throat. Soft and open. And the space around your neck. In front. Behind. On either side.\n[pause 12s]\nYour shoulders. Let them melt. Now sense the space above your shoulders, and the space around them.\n[pause 12s]\nBring your attention down your arms, into your hands. Feel your hands from the inside. Their weight. Their aliveness.\n[pause 10s]\nNow sense the space around your hands. The air touching the backs of your hands. The space between each finger. The space cupped in each palm.\n[pause 15s]\nYour chest. Feel the breath moving there. Now sense the space in front of your chest. And the space behind your back. Your chest held in a sphere of space.\n[pause 15s]\nYour belly. Soft and easy. And the space around your belly, the whole width of your waist.\n[pause 12s]\nYour hips and pelvis. Heavy and grounded. And the space around your hips.\n[pause 12s]\nYour legs. Your thighs, your knees, your shins. And the length of space alongside them.\n[pause 12s]\nYour feet. Feel the soles, the heels, the toes. And the space beneath your feet, and around them.\n[pause 15s]\nNow become aware of your whole body at once, from head to feet. The full shape of you.\n[pause 12s]\nAnd now the space all around that shape. Above you. Below you. In front. Behind. To the left and to the right.\n[pause 15s]\nLet your awareness keep growing. Wider than your body. As wide as the room. Wider than the room. As wide as the sky.\n[pause 15s]\nNotice that your attention is not stuck inside your body. It can rest anywhere. It can rest everywhere.\n[silence]\nStay here, as wide, open awareness, holding the body gently at its centre.\n"}}},863,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"breath",{enumerable:!0,get:function(){return t}});const t={id:'breath',title:'Breathe',subtitle:'Slow, deep, easy breathing',ambient:{bed:'drift',level:.75,binaural:'alpha'},scripts:{short:"\nBring your attention to your breath.\n\nBreathe in slowly through your nose, letting your belly rise.\n[pause 4s]\nAnd breathe out, long and slow, a little longer than the breath in.\n[pause 6s]\nAgain. In through the nose, filling low and wide.\n[pause 4s]\nAnd a long, unhurried breath out.\n[pause 6s]\nEach breath out tells your body that it is safe. That it can let go.\n[pause 6s]\nKeep this rhythm on your own now. Slow in. Slower out.\n[silence]\nLet the breath find its own easy pace.\n",medium:"\nNow bring your attention to your breathing.\n\nDon't change anything yet. Just notice it. The cool air entering. The warm air leaving. The gentle rise and fall.\n[pause 10s]\nNow let's deepen it. Breathe in slowly through your nose, and let the breath sink all the way down, so your belly expands first, then your ribs.\n[pause 5s]\nPause for a moment at the top.\n[pause 2s]\nAnd breathe out slowly, softly, letting the belly fall.\n[pause 7s]\nAgain. Breathing in, low and wide.\n[pause 5s]\nResting at the top.\n[pause 2s]\nAnd a long, smooth breath out, as if you were breathing out through a straw.\n[pause 7s]\nWith every breath out, feel your body grow a little heavier and a little quieter.\n[pause 8s]\nContinue on your own now. In for a slow count of four. Out for a slow count of six.\n[silence]\nLet the breath become effortless. You don't need to manage it any more. Just let it breathe you.\n",long:"\nNow bring your attention to your breathing.\n\nTo begin, don't change it at all. Simply notice it, the way you might watch waves arriving at a shore.\n\nNotice where you feel it most. Perhaps the cool air at the tip of your nose. Perhaps the movement in your chest, or your belly.\n[pause 15s]\nNow, let's guide it gently. Breathe in slowly through your nose, and let the breath travel all the way down, so that your belly softens and rises first, then your lower ribs widen, then your chest.\n[pause 5s]\nHold it softly at the top.\n[pause 3s]\nAnd let it go slowly, emptying from the top down. Chest. Ribs. Belly.\n[pause 8s]\nAgain. Breathing in, low and slow, filling from the bottom up.\n[pause 5s]\nResting at the top.\n[pause 3s]\nAnd a long, unhurried breath out.\n[pause 8s]\nOne more like this. In, filling completely.\n[pause 5s]\nPause.\n[pause 3s]\nAnd out, slowly, all the way to the end of the breath.\n[pause 8s]\nNotice how even three slow breaths have changed something. The body has received the message. It is safe to slow down.\n[pause 10s]\nNow keep this rhythm on your own. Breathing in for a slow count of four. Breathing out for a slow count of six or seven. The breath out always a little longer than the breath in.\n[pause 30s]\nWith each breath out, let a little more tension leave your body. From your face. From your neck and shoulders. From your hands.\n[pause 25s]\nIf your mind wanders, that's fine. That's what minds do. Each time you notice, simply return to the next breath. Returning is the practice.\n[silence]\nNow let go of any counting. Let the breath return to its own natural rhythm. Slow, soft, and easy, all on its own.\n"}}},864,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"closing",{enumerable:!0,get:function(){return n}});const n={id:'closing',title:'Return',subtitle:'Bring it with you',ambient:{bed:'drift',level:.6,binaural:'off'},scripts:{short:"\nNow let the images fade, and keep the feeling.\n[pause 4s]\nTake a deeper breath in.\n[pause 3s]\nAnd let it go.\n[pause 3s]\nBegin to notice your body again. Your hands. Your feet. The surface beneath you.\n[pause 5s]\nGently move your fingers and toes.\n[silence]\nWhen you are ready, open your eyes, and carry this with you into your day.\n",medium:"\nNow slowly let the scene fade, but keep the feeling. It belongs to you now.\n[pause 6s]\nGive thanks, in your own words, for this time you have given yourself. And for the future that is already on its way.\n[pause 10s]\nBegin to come back. Take a slightly deeper breath in.\n[pause 4s]\nAnd let it go with a sigh.\n[pause 5s]\nNotice your body again. The weight of your hands. The contact of your feet. The sounds of the room around you.\n[pause 6s]\nGently move your fingers and your toes. Roll your shoulders. Stretch in any way that feels good.\n[silence]\nAnd when you are ready, open your eyes. Take one moment to look around before you move on. You can return to this feeling whenever you choose.\n",long:"\nNow slowly let the images fade. You don't need to hold on to them. The feeling stays with you.\n[pause 8s]\nTake a moment to give thanks. For this time you have given yourself. For your body, which has carried you here. For the future that is already on its way.\n[pause 15s]\nSet a quiet intention to come back to this feeling, again and again, throughout your day. When you notice old habits arising, you can simply remember. Breathe into your heart, and choose again.\n[pause 12s]\nNow begin to return.\n\nTake a slightly deeper breath in.\n[pause 4s]\nAnd let it go with a sigh.\n[pause 6s]\nAnother deeper breath in, filling all the way.\n[pause 4s]\nAnd let it go.\n[pause 6s]\nNotice the weight of your body. The surface beneath you. The temperature of the air on your skin.\n[pause 8s]\nNotice the sounds around you, growing a little clearer.\n[pause 8s]\nBegin to move. Your fingers. Your toes. Gently turn your head from side to side.\n[pause 8s]\nStretch in any way your body asks for.\n[silence]\nAnd when you are ready, slowly open your eyes. Let them adjust to the light. Take a moment before you move on.\n\nWelcome back. Carry this with you.\n"}}},865,[]);
